//! JSON schemas for every tool parameter model, generated by
//! `scripts/gen_tool_schemas.py` from `engine/.../tool_models.py` into
//! `tool_schemas.json`. Used for planner prompts (operation descriptions and
//! parameter descriptions) and as the `final_result` schema during parameter
//! selection until the typify `tool_params` models land.

use std::collections::HashMap;
use std::sync::LazyLock;

use serde_json::Value;

use crate::models::tool_models::ToolEndpoint;

static SCHEMAS: LazyLock<HashMap<String, Value>> = LazyLock::new(|| {
    serde_json::from_str(include_str!("tool_schemas.json"))
        .expect("tool_schemas.json must be valid JSON")
});

/// The parameter model's JSON schema, or `None` for endpoints without one.
pub fn tool_schema(endpoint: ToolEndpoint) -> Option<&'static Value> {
    SCHEMAS.get(endpoint.as_str())
}

/// `OPERATIONS[op].model_json_schema()["description"]`, trimmed.
pub fn operation_description(endpoint: ToolEndpoint) -> String {
    tool_schema(endpoint)
        .and_then(|s| s.get("description"))
        .and_then(Value::as_str)
        .unwrap_or("")
        .trim()
        .to_string()
}

/// `(name, description)` for each declared parameter, in schema order.
pub fn operation_parameters(endpoint: ToolEndpoint) -> Vec<(String, String)> {
    let Some(schema) = tool_schema(endpoint) else {
        return Vec::new();
    };
    schema
        .get("properties")
        .and_then(Value::as_object)
        .map(|props| {
            props
                .iter()
                .map(|(name, prop)| {
                    (
                        name.clone(),
                        prop.get("description")
                            .and_then(Value::as_str)
                            .unwrap_or("")
                            .trim()
                            .to_string(),
                    )
                })
                .collect()
        })
        .unwrap_or_default()
}
